<?php require dirname(__DIR__).'/partials/fields.php'; ?>
<div class="page-head"><div><h1>Tenant Login Security</h1><div class="subtitle">IP blocks here apply only to the active tenant domain. Global SIP/Fail2ban remains under superadmin control.</div></div></div>
<?php if(auth()->can('tenant_security.manage')): ?><form method="post" action="/tenant-security" class="card mb-4"><?= csrf() ?><div class="card-head"><h2>Block IP for this tenant</h2></div><div class="card-body"><div class="form-grid"><?= field_text('ip','IPv4 or IPv6 address','',['required'=>true,'placeholder'=>'203.0.113.10']) ?><?= field_text('reason','Reason','',['placeholder'=>'Repeated login failures']) ?></div></div><div class="card-foot"><button class="btn btn-primary" data-confirm-btn="Block this IP for the active tenant?">Block IP</button></div></form><?php endif; ?>
<div class="card"><div class="card-head"><h2>Blocked IP addresses</h2><span class="badge blue"><?= count($rows) ?></span></div><div class="card-body tight"><?php if(!$rows): ?><p class="muted">No IP addresses are blocked for this tenant.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>IP</th><th>Reason</th><th>Added by</th><th>Date</th><?php if(auth()->can('tenant_security.manage')):?><th class="actions">Actions</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $row):?><tr><td class="mono"><?= e($row['ip']) ?></td><td><?= e($row['reason']?:'—') ?></td><td><?= e($row['created_by_name']?:'—') ?></td><td><?= e(format_date($row['created_at'])) ?></td><?php if(auth()->can('tenant_security.manage')):?><td class="actions"><form method="post" action="/tenant-security/<?= (int)$row['id'] ?>"><?= csrf() ?><input type="hidden" name="_method" value="DELETE"><button class="btn btn-sm btn-ghost" data-confirm-btn="Unblock this IP?">Unblock</button></form></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div>
